describe("doctests of sympy.integrals", () => {
  it("integrate(1/x,x)", () => {
    const x = new Sym('x');
    expect(sympyStr(integrate(pow(x, -1), x))).toBe('log(x)');
  });
  it("integrate(sin(x),x)", () => {
    const x = new Sym('x');
    expect(sympyStr(integrate(fn('sin', [x]), x))).toBe('-cos(x)');
  });
});

